            input_types=["Data", "JSON"],
        ),
        DataInput(
            name="fallback_design_result",
            display_name="1차 검증 설계 결과(보완 실패 시 사용)",
            info="최종 보완 모델을 사용할 수 없을 때 이미 검증된 1차 설계 결과를 안전하게 유지합니다. 최종 정규화 인스턴스에만 07의 결과를 연결합니다.",
