      path.setAttribute("class", `edge-path ${edgeClass(cleanText(edge.edge_kind))}`);
      path.setAttribute("stroke-width", cleanText(edge.edge_kind) === "branch" ? "2.25" : "2");
      path.setAttribute("marker-end", `url(#${markerId})`);
