  }, true);

  closeButton.addEventListener("click", (event) => {
    event.stopImmediatePropagation();
    closeHumanDrawer();
  }, true);
  backdrop.addEventListener("click", (event) => {
    event.stopImmediatePropagation();
    closeHumanDrawer();
